  ('ROUND_TABLE', 'ACCUSATION', 'Carismático', '{user} olhou para {user1}: "Você liderou o ataque contra {victim}. Amanhã é a sua vez de explicar."'),
  ('ROUND_TABLE', 'NEUTRAL', NULL, '{user} pediu a palavra, respirou fundo e admitiu que ainda não tinha decidido o voto.'),
  ('ROUND_TABLE', 'ALLIANCE', 'Fiel', '{user} olhou para {user1} antes de votar. Os dois assentiram ao mesmo tempo.'),

  -- ------------------------------------------------------------ torre dos traidores
  ('TRAITORS_MEETING', 'STRATEGY', 'Estrategista', '{user} abriu o mapa do castelo sobre a mesa: "{user1} está chegando perto demais. É hoje."'),
  ('TRAITORS_MEETING', 'STRATEGY', 'Astuto', '"Se matarmos {user1}, vão desconfiar de quem brigou com ele(a) ontem", calculou {user}.'),
  ('TRAITORS_MEETING', 'STRATEGY', 'Manipulador', '{user} sugeriu deixar {user1} vivo(a): "A mesa redonda vai banir por nós."'),
  ('TRAITORS_MEETING', 'STRATEGY', 'Invejoso', '{user} sorriu: "Todo mundo ama {user1}. Por isso mesmo."'),
  ('TRAITORS_MEETING', 'STRATEGY', 'Manipulador', '"{user1} confia em mim cegamente. Isso vale mais vivo do que morto", disse {user}.'),
  ('TRAITORS_MEETING', 'STRATEGY', 'Competitivo', '{user} riscou o nome de {user1} na lista: "Ameaça. Ponto final."'),
  ('TRAITORS_MEETING', 'STRATEGY', NULL, '{user} propôs matar {user1} para jogar a suspeita em cima de quem o(a) acusou.'),
  ('TRAITORS_MEETING', 'STRATEGY', 'Estrategista', '{user} avisou {user2}: "Se você continuar defendendo {user1} na mesa, vão desconfiar de você."'),
  ('TRAITORS_MEETING', 'STRATEGY', 'Carismático', '{user} garantiu que amanhã convence a mesa inteira de que {user1} é o(a) culpado(a).'),
  ('TRAITORS_MEETING', 'CONFLICT', 'Explosivo', '{user} e {user2} discutiram por causa de {user1} e quase apagaram as velas da torre.'),
  ('TRAITORS_MEETING', 'CONFLICT', NULL, '"Você está ficando mole, {user2}", disse {user}, quando {user2} hesitou em escolher {user1}.'),
  ('TRAITORS_MEETING', 'CONFLICT', 'Paranoico', '{user} desconfia que {user2} vai traí-lo(a) na próxima mesa redonda.'),
  ('TRAITORS_MEETING', 'HUMOR', 'Dramático', '{user} brincou: "Amanhã no café eu vou chorar mais que todo mundo."'),
