  ('TRAITORS_MEETING', 'EMOTION', 'Fiel', '{user} confessou a {user2} que não aguenta mais mentir para {user1}.'),
  ('TRAITORS_MEETING', 'NEUTRAL', 'Tímido', '{user} acendeu as velas e esperou os outros em silêncio.'),

  -- ------------------------------------------------------------ mesa final
  ('ENDGAME', 'ACCUSATION', 'Paranoico', '"Chegamos até aqui e eu ainda não confio em {user1}", disse {user}.'),
  ('ENDGAME', 'ACCUSATION', 'Competitivo', '{user} pediu mais uma rodada: "Não vou dividir o prêmio com {user1}."'),
  ('ENDGAME', 'ACCUSATION', NULL, '{user} olhou para {user1}: "Se eu estiver errado(a), me perdoa. Mas eu preciso ter certeza."'),
  ('ENDGAME', 'DEFENSE', 'Fiel', '{user} segurou a mão de {user1}: "Eu sei quem você é. Vamos encerrar."'),
  ('ENDGAME', 'DEFENSE', NULL, '"{user1} provou que é Fiel dez vezes", insistiu {user}, encarando {user2}.'),
  ('ENDGAME', 'EMOTION', 'Dramático', '{user} chorou lembrando de todos que ficaram pelo caminho.'),
  ('ENDGAME', 'EMOTION', NULL, '"Eu nunca menti para vocês", disse {user}, com a mão no peito.'),
  ('ENDGAME', 'EMOTION', 'Tímido', '{user} ficou em silêncio por um longo minuto antes de conseguir falar.'),
  ('ENDGAME', 'SUSPICION', 'Paranoico', '{user} olhou para cada rosto da mesa: "Um de vocês ainda está mentindo."'),
  ('ENDGAME', 'SUSPICION', NULL, '{user} lembrou que {user1} nunca votou num Traidor. Nenhuma vez.'),
  ('ENDGAME', 'ALLIANCE', 'Fiel', '{user} e {user1} trocaram um olhar: chegaram juntos e querem sair juntos.'),
  ('ENDGAME', 'CONFLICT', 'Explosivo', '{user} explodiu com {user1}: "Você me usou o jogo inteiro!"'),
  ('ENDGAME', 'CONFLICT', 'Invejoso', '{user} disse a {user1}: "Você não merece um centavo desse prêmio."')
